   void Check(bool ok,string code,string scope){checks++;if(!ok)findings.Add(new JsonObject{{"code",JsonValue.CreateStringValue(code)},{"scope",JsonValue.CreateStringValue(scope)}});}
   Color ColorOf(Brush brush)=>brush is SolidColorBrush solid?solid.Color:brush is LinearGradientBrush gradient&&gradient.GradientStops.Count>0?gradient.GradientStops.Last().Color:Colors.Transparent;
   string Ink(Brush brush)=>ColorOf(brush).ToString();
   try
   {
