    _onexThemeQaStore=true;isThemeInitialized=false;isGlassToggleInitialized=true;foreach(var tab in tabs)tab.Visibility=Visibility.Visible;
    SystemNavItem.IsChecked=true;body.Children.Insert(0,card);ConfigureOnexFocus(fixture);
    foreach(string name in OnexAllowedThemeNames)
    {
     isThemeInitialized=false;ApplyTheme(name);var theme=WidgetThemes[name];
     var colors=new JsonObject{{"name",JsonValue.CreateStringValue(name)},{"expectedText",JsonValue.CreateStringValue(theme.TextPrimary.ToString())},{"expectedCard",JsonValue.CreateStringValue(theme.CardBackground.ToString())}};
     foreach(bool glass in new[]{false,true})
     {
      lastOwnGlass=glass;if(GlassEffectToggle.IsOn==glass)GlassEffectToggle_Toggled(GlassEffectToggle,null);else GlassEffectToggle.IsOn=glass;
      foreach(var tab in tabs)
      {
       tab.IsChecked=true;UpdateLayout();await Task.Delay(50);var root=OnexNavigationRoot();string scope=name+"/"+glass+"/"+(tab.Tag as string);
       Check(_onexAppliedTheme?.Name==name,"palette_changed_after_navigation",scope);Check(root!=null,"missing_page_root",scope);if(root==null)continue;
       var sectionHeaders=OnexOwnedContent(root).OfType<ToggleButton>().Where(x=>x.Name.EndsWith("ExpandButton",StringComparison.Ordinal)||IsOnexSettingsSectionHeader(x)).ToArray();
       bool oldProjection=_onexSettingsHeaderQaProjection;_onexSettingsHeaderQaProjection=true;
       try{foreach(var header in sectionHeaders){if(!headers.ContainsKey(header))headers[header]=header.IsChecked;header.IsChecked=true;}UpdateLayout();await Task.Delay(30);}finally{_onexSettingsHeaderQaProjection=oldProjection;}
       var nodes=OnexOwnedContent(root).OfType<FrameworkElement>().Where(x=>x.IsLoaded&&x.Visibility==Visibility.Visible).ToArray();
       pages.Add(new JsonObject{{"palette",JsonValue.CreateStringValue(name)},{"glass",JsonValue.CreateBooleanValue(glass)},{"tab",JsonValue.CreateStringValue(tab.Tag as string??"")},{"actualPalette",JsonValue.CreateStringValue(_onexAppliedTheme?.Name??"")},{"actualTheme",JsonValue.CreateStringValue(root.ActualTheme.ToString())},{"publicLogicalNodes",JsonValue.CreateNumberValue(nodes.Length)},{"expandedHeaders",JsonValue.CreateNumberValue(sectionHeaders.Length)}});
       foreach(var hint in new[]{OnexLtHint,OnexRtHint})if(hint.Child is TextBlock text)Check(OnexContrast(ColorOf(text.Foreground),ColorOf(hint.Background))>=4.5,"navigation_badge_contrast",scope);
       if(name==OnexPalette.Name&&!glass)
       {
        int ordinal=0;foreach(var element in nodes.OfType<Control>())
         controls.Add(new JsonObject{{"tab",JsonValue.CreateStringValue(tab.Tag as string??"")},{"ordinal",JsonValue.CreateNumberValue(ordinal++)},{"name",JsonValue.CreateStringValue(knownNames.Contains(element.Name)?element.Name:"")},{"type",JsonValue.CreateStringValue(element.GetType().Name)},{"enabled",JsonValue.CreateBooleanValue(element.IsEnabled)},{"tabStop",JsonValue.CreateBooleanValue(element.IsTabStop)},{"width",JsonValue.CreateNumberValue(element.ActualWidth)},{"height",JsonValue.CreateNumberValue(element.ActualHeight)}});
       }
       if(ReferenceEquals(tab,SystemNavItem))
       {
        colors[glass?"aboutGlass":"aboutOpaque"]=new JsonObject{{"background",JsonValue.CreateStringValue(Ink(OnexAboutCard.Background))},{"captionInk",JsonValue.CreateStringValue(Ink(OnexSupportAuthorCaption.Foreground))},{"rootBackground",JsonValue.CreateStringValue(Ink(Background))},{"actualPalette",JsonValue.CreateStringValue(_onexAppliedTheme?.Name??"")}};
        Check(OnexContrast(ColorOf(OnexSupportAuthorCaption.Foreground),ColorOf(OnexAboutCard.Background))>=4.5,"about_caption_contrast",scope);
       }
       if(ReferenceEquals(tab,PerformanceNavItem))
       {
        var slider=_releaseHome.FindName("OnexPl2Slider") as Slider;
        colors[glass?"pl2Glass":"pl2Opaque"]=new JsonObject{{"actual",JsonValue.CreateStringValue(Ink(slider?.Foreground))},{"oldTestExpected",JsonValue.CreateStringValue((name==OnexPalette.Name?OnexPalette.Violet:theme.EffectiveAccent()).ToString())},{"themeAccent",JsonValue.CreateStringValue(theme.EffectiveAccent().ToString())}};
       }
       pageVisits++;
      }
     }
     SystemNavItem.IsChecked=true;card.Visibility=Visibility.Visible;card.StartBringIntoView(new BringIntoViewOptions{AnimationDesired=false});UpdateLayout();fixture.IsDropDownOpen=true;await Task.Delay(100);
     var popupRows=new JsonArray();
     foreach(int selected in new[]{0,1,2})
     {
      fixture.SelectedIndex=selected;await Task.Delay(20);UpdateLayout();
      foreach(var item in fixture.Items.OfType<ComboBoxItem>())
      {
       item.ApplyTemplate();var itemRoot=VisualTreeHelper.GetChildrenCount(item)>0?VisualTreeHelper.GetChild(item,0) as FrameworkElement:null;
       var surface=itemRoot?.FindName("OwnSurface") as Border;if(surface==null){Check(false,"missing_owned_popup_template",name);continue;}
       foreach(string state in new[]{"Normal","PointerOver","Pressed"})
       {
        VisualStateManager.GoToState(item,state,false);await Task.Delay(3);
        Color actualInk=ColorOf((itemRoot?.FindName("OwnChoiceContent") as ContentPresenter)?.Foreground??item.Foreground),expectedInk=item.IsSelected?(theme.SelectionText??theme.TextPrimary):theme.TextPrimary,bg=ColorOf(surface.Background);
        double actualRatio=OnexContrast(actualInk,bg),expectedRatio=OnexContrast(expectedInk,bg);
        popupRows.Add(new JsonObject{{"selected",JsonValue.CreateBooleanValue(item.IsSelected)},{"state",JsonValue.CreateStringValue(state)},{"ink",JsonValue.CreateStringValue(actualInk.ToString())},{"expectedInk",JsonValue.CreateStringValue(expectedInk.ToString())},{"background",JsonValue.CreateStringValue(bg.ToString())},{"actualContrast",JsonValue.CreateNumberValue(actualRatio)},{"oldTestContrast",JsonValue.CreateNumberValue(expectedRatio)}});
        Check(actualRatio>=4.5,"popup_text_contrast",name+"/"+state+"/"+item.IsSelected);popupSamples++;
       }
      }
     }
     fixture.IsDropDownOpen=false;colors["popupStates"]=popupRows;palettes.Add(colors);
     report["completedPalettes"]=JsonValue.CreateNumberValue(palettes.Count);
     await FileIO.WriteTextAsync(await ApplicationData.Current.LocalFolder.CreateFileAsync("regression100-ui-progress.json",CreationCollisionOption.ReplaceExisting),report.Stringify());
    }
    report["checks"]=JsonValue.CreateNumberValue(checks);report["findings"]=findings;report["palettes"]=palettes;report["pageCases"]=pages;report["controls"]=controls;report["actualPageVisits"]=JsonValue.CreateNumberValue(pageVisits);report["actualPopupStateSamples"]=JsonValue.CreateNumberValue(popupSamples);report["publicControlInventoryCount"]=JsonValue.CreateNumberValue(controls.Count);
    report["privateLabelsExported"]=JsonValue.CreateBooleanValue(false);report["physicalInputTested"]=JsonValue.CreateBooleanValue(false);report["ownerThemePreferenceWritten"]=JsonValue.CreateBooleanValue(false);
    if(findings.Count>0)throw new InvalidOperationException("Systematic UI findings recorded; inspect data, not assumed all-pass");
   }
   finally
   {
    fixture.IsDropDownOpen=false;body.Children.Remove(card);bool projection=_onexSettingsHeaderQaProjection;_onexSettingsHeaderQaProjection=true;foreach(var pair in headers)pair.Key.IsChecked=pair.Value;_onexSettingsHeaderQaProjection=projection;
    isGlassToggleInitialized=false;isThemeInitialized=false;
    if(lastOwnGlass.HasValue&&prefs.TryGetValue(OnexGlassSurfaces.Setting,out var latest)&&latest is bool own&&own==lastOwnGlass.Value){if(hadGlass)prefs[OnexGlassSurfaces.Setting]=oldGlass;else prefs.Remove(OnexGlassSurfaces.Setting);}
    GlassEffectToggle.IsOn=IsGlassEffectEnabled();ApplyTheme(prefs.TryGetValue("WidgetTheme",out var fresh)?fresh as string:OnexPalette.Name);isGlassToggleInitialized=glassReady;isThemeInitialized=themeReady;_onexThemeQaStore=themeStore;
    for(int n=0;n<tabs.Length;n++)tabs[n].Visibility=visibility[n];if(original?.Visibility==Visibility.Visible)original.IsChecked=true;
   }
